const request = $input.first().json;
return {
  json: {
    authorization: request.headers?.authorization || '',
    required_roles: ["admin"],
    required_capability: "",
    request,
  },
};

const guard = $('Run Auth Guard').first().json;
if (!guard.ok) {
  return {
    json: {
      http_status: guard.status,
      body: { success: false, error: guard.code, message: guard.message },
    },
  };
}
return {
  json: {
    ok: true,
    sql: `
      SELECT id, name, status
      FROM performance_db.evaluation_periods
      WHERE is_active = true OR status = 'active'
      LIMIT 1
    `,
  },
};

const prev = $('Check Freeze').first().json;
if (prev.http_status) {
  return { json: prev };
}
const activePeriod = $input.all().map(item => item.json).find(item => item.id !== undefined);
if (activePeriod) {
  return {
    json: {
      http_status: 409,
      body: {
        success: false,
        error: 'ACTIVE_PERIOD_EXISTS',
        message: `Cannot modify grade coefficients while period "${activePeriod.name}" is active`,
      },
    },
  };
}
const guard = $('Run Auth Guard').first().json;
// Генерируем SQL запросы для обновления
const body = (guard.request.body || guard.request);
const grades = body.grades || [];
const settings = body.settings || [];

let sqlQueries = [];

// 1. Обновляем Грейды
for (const g of grades) {
  if (g.id && g.coefficient !== undefined) {
     sqlQueries.push(`UPDATE performance_db.grades SET coefficient = ${g.coefficient} WHERE id = ${g.id};`);
  }
}

// 2. Обновляем Настройки
for (const s of settings) {
  if (s.setting_key && s.setting_value !== undefined) {
    sqlQueries.push(`UPDATE performance_db.global_settings SET setting_value = ${s.setting_value} WHERE setting_key = '${s.setting_key}';`);
  }
}

const finalQuery = sqlQueries.join('\n');

return {
  json: {
    query: finalQuery,
    count: sqlQueries.length
  }
};

const prev = $('Build SQL').first().json;
if (prev.http_status) {
  return { json: prev };
}
return {
  json: {
    http_status: 200,
    body: {
      success: true,
      message: 'Данные успешно обновлены',
      updatedCount: prev.count || 0,
    },
  },
};
